CREATE TABLE IF NOT EXISTS cap19_categories (category_id INTEGER PRIMARY KEY, category_name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS cap19_products (product_id INTEGER PRIMARY KEY, category_id INTEGER NOT NULL REFERENCES cap19_categories(category_id), product_name TEXT NOT NULL, unit_price REAL NOT NULL CHECK (unit_price >= 0), stock_qty INTEGER NOT NULL CHECK (stock_qty >= 0));
INSERT OR IGNORE INTO cap19_categories VALUES (1, 'Accessories'), (2, 'Stationery');
INSERT OR IGNORE INTO cap19_products VALUES (1, 1, 'USB Cable', 250, 20), (2, 1, 'Phone Case', 400, 12), (3, 2, 'Notebook', 60, 50);
CREATE TABLE IF NOT EXISTS cap19_customers (customer_id INTEGER PRIMARY KEY, customer_name TEXT NOT NULL, phone TEXT UNIQUE);
CREATE TABLE IF NOT EXISTS cap19_orders (order_id INTEGER PRIMARY KEY, customer_id INTEGER NOT NULL REFERENCES cap19_customers(customer_id), order_date TEXT NOT NULL, order_status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS cap19_order_items (order_item_id INTEGER PRIMARY KEY, order_id INTEGER NOT NULL REFERENCES cap19_orders(order_id), product_id INTEGER NOT NULL REFERENCES cap19_products(product_id), quantity INTEGER NOT NULL CHECK (quantity > 0), unit_price REAL NOT NULL CHECK (unit_price >= 0));

